INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "春咲 ひより", 1001, "お！\nあそこに困ってそうな人発見！", 1, 0, 0, 0, 0, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "草野 優衣", 1002, "大切な人を\n守れるようになりたい…って", 1, 0, 0, 0, 0, "わ、わたし、\nなに言ってるんだろ\nあはは…", "みんなみたいに\nわたしも強くならなきゃ", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "士条 怜", 1003, "キミに必要な集中力と感性が", 1, 0, 0, 0, 0, "少しは磨かれると思いますよ。", "フェンシングを始めてみては？", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.5, "穂高 みそぎ", 1004, "今日はなにして遊ぶ？", 1, 0, 0, 0, 0, "みそぎはねぇ、\nかくれんぼやりたい！", "ねぇ、にいちゃん！", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "風宮 あかり", 1006, "ねぇ…", 1, 0, 0, 0, 0, "私といっしょに…\nいかない？", "風宮あかりです", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.5, "出雲 宮子", 1007, "プリンたべたいのー", 1, 0, 0, 0, 0, "食べ物の恨みは怖いのー", "出雲宮子なのー", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "虹村 雪", 1008, "キミもボクの美貌に\n吸い寄せられたんだね。", 1, 0, 0, 0, 0, "いいよ。\n見られることは運命さ…", "ボクは虹村雪。", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "柊杏奈", 1009, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 1, 0, 0, 0, 0, "人呼んで「疾風の冥姫」!!", "フッ…聞いて後悔するがいい！", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.5, "姫宮 真歩", 1010, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 1, 0, 0, 0, 0, "ほんまおおきにやわ～♪", "マホマホ王国のプリンセス、\nまほ姫どす", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "衣之咲 璃乃", 1011, "生き別れたお兄ちゃんを探して\n三千世界！", 1, 0, 0, 0, 0, "ここで会ったが\n100年目～！", "衣之咲璃乃です！", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "柏崎 初音", 1012, "ち、超能力って…\n何のことかな～？", 1, 0, 0, 0, 0, "…って、お願い！\n誰にも言わないでおいて～！", "私はハツネ、\n結構強いんだよ。\nきらーん☆", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "美波 鈴奈", 1016, "一応カリスマ読モJKやってまっす！", 1, 0, 0, 0, 0, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", "ちょす！\n美波鈴奈だよ～♪", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "喜屋武 香織", 1017, "東京は遊園地みたいなところさー", 1, 0, 0, 0, 0, "でも、沖縄もとってもいいとこさー", "はいたーい。\n喜屋武香織さー。", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "支倉 伊緒", 1018, "先生って呼ばれるのは\nくすぐったいから", 1, 0, 0, 0, 0, "イオちゃんって呼んでね。", "支倉伊緒です。", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.5, "茜 ミミ", 1020, "あ！/\お兄ちゃ～ん\nまってよ～", 1, 0, 0, 0, 0, "ミミをおいてかないでぇ～", "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.5, "栗林 くるみ", 1021, "あの……\nふぇ……", 1, 0, 0, 0, 0, "ふぇぇぇぇぇん……", "あ…あの…えっと…\n栗…林…くるみ…です……", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "風宮 より", 1022, "こんな私に貴重な時間を\n割いていただき、", 1, 0, 0, 0, 0, "なんてありがとうございます！", "風宮よりです。\nあああああ！", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.5, "北条 綾音", 1023, "おにいちゃんどこいくの？\nえ？", 1, 0, 0, 0, 0, "私こっち行きたいー\nね、早く早くー", "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "天野 すずめ", 1025, "ふ、不束者ですが\nどうぞ末永く…って、", 1, 0, 0, 0, 0, "これて何か違う…\nあああすみません！", "わっ…わっ…私、\n天野すずめといいます！", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "倉石 恵理子", 1027, "あなたは…運命の……\n伴侶……", 1, 0, 0, 0, 0, "離しませんわ………\n絶対に…!!", "……クスクス…私は\n…倉石恵理子……", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "佐々木 咲恋", 1028, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 1, 0, 0, 0, 0, "…そうでしょ？？", "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "桜井 望", 1029, "ぇっと…\nキミ、私のこと知らないの?!", 1, 0, 0, 0, 0, "あはは、\n私もまだまだだなぁ～", "桜井望だよ！\nよろしくねっ", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "ニノン・ジュベール", 1030, "初めまして、\n私はニノン・ジュベール申すデス！", 1, 0, 0, 0, 0, "ショーグン、\nワタシと一緒に天下統一デース！", "デケデケデンっ！", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "上喜 しのぶ", 1031, "でもって私の隣にいるのが……\nえ、見えない？", 1, 0, 0, 0, 0, "おかしいですね……", "上喜しのぶです。\n手元のドクロが父です。", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.5, "野戸まひる", 1033, "けんども\nそれには足りないモンが…", 1, 0, 0, 0, 0, "そう、\nオラのボケに突っ込める相方が…！", "目指すはビッグな\nお笑い芸人だっぺ！", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "綾瀬 ゆかり", 1034, "ちょっと緊張しちゃって…", 1, 0, 0, 0, 0, "ちょ\nちょっと一杯飲んできます…！", "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.5, "氷川 鏡華", 1036, "知らない人とは話しちゃいけないので", 1, 0, 0, 0, 0, "これ以上お話しすることは…\nないです！", "氷川鏡華…です", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "柏崎 栞", 1038, "……あ、アラーム。", 1, 0, 0, 0, 0, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", "柏崎…栞です。", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "双葉 碧", 1040, "私、一人も友達がいなくて……", 1, 0, 0, 0, 0, "野に咲く花が、\n唯一の話相手です。", "ふ、双葉碧です。", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "三角 千歌", 1042, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 1, 0, 0, 0, 0, "そう思っています。", "三角千歌です。", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "安芸 真琴", 1043, "あぁ？\nお前のそいつの仲間か？", 1, 0, 0, 0, 0, "う、疑ってすまなかったな…", "安芸真琴だ。", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "イリヤ・オーンスタイン", 1044, "生けとし生ける全ての者よ！", 1, 0, 0, 0, 0, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", "わらわこそは夜を総べる者！", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "遠見 空花", 1045, "ぐふふふふ……はっ！", 1, 0, 0, 0, 0, "ｌク、クウカに何かご用ですか!?", "そこで騎士は妖精を乱暴に……", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "宮坂たまき", 1046, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 1, 0, 0, 0, 0, "う～ん…\n猫ってホントに最高にゃ～♪", "宮坂たまきにゃ♪\n猫はいいにゃよ？", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "大神 美冬", 1048, "それでは早速クエストに…", 1, 0, 0, 0, 0, "…と思ったら\nバイトの時間だ！\nまたあとでね！", "大神美冬よ！", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "星野静流", 1049, "クエストもバトルも\n掃除も洗濯も", 1, 0, 0, 0, 0, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", "星野静流だよ！", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.5, "玉泉美咲", 1050, "見ての通りの\nセクシー美少女で", 1, 0, 0, 0, 0, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", "アタシは玉泉美咲。", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.4, "リマ", 1052, "？？？？", 1, 0, 0, 0, 0, "？？？？", "？？？", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.5, "モニカ・ヴァイスヴィント", 1053, "菓子でつろうなどと\n稚拙な策を……", 1, 0, 0, 0, 0, "そ、そこまでいうなら\nもらってやる", "モニカ・ヴァイスヴィントだ。", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.5, "ペコリーヌ", 1058, "菓子でつろうなどと\n稚拙な策を……", 1, 0, 0, 0, 0, "そ、そこまでいうなら\nもらってやる", "モニカ・ヴァイスヴィントだ。", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.5, "コッコロ", 1059, "菓子でつろうなどと\n稚拙な策を……", 1, 0, 0, 0, 0, "そ、そこまでいうなら\nもらってやる", "モニカ・ヴァイスヴィントだ。", 1, 2, 0);
INSERT INTO `v1_b7573d32ae9d58a407bef1cdfce407d0c3832d10c415b5396267ce71e56a6b92` VALUES (1, 1.5, "キャル", 1060, "菓子でつろうなどと\n稚拙な策を……", 1, 0, 0, 0, 0, "そ、そこまでいうなら\nもらってやる", "モニカ・ヴァイスヴィントだ。", 1, 2, 0);
